INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Nom de domaine : bien le choisir et le garder à votre nom', 'nom-de-domaine-entreprise', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Votre nom de domaine, c''est l''adresse de votre site et de vos e-mails. Mal choisi ou déposé au nom d''un prestataire, il peut vous coûter cher. Le guide pour bien faire.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Le nom de domaine est l''adresse de votre site et de vos e-mails professionnels : il doit être court, facile à dicter au téléphone, et à votre nom.</li> <li>À La Réunion, l''extension .re montre votre ancrage local ; .fr et .com restent des valeurs sûres. Beaucoup d''entreprises en réservent deux et redirigent l''une vers l''autre.</li> <li>Le point le plus important : c''est votre entreprise qui doit être titulaire du nom, pas votre prestataire, avec un renouvellement automatique.</li> </ul> </div> <p>« Le site, c''est mon ancien prestataire qui l''a fait. Il ne répond plus, et je ne peux même pas changer l''adresse e-mail. » Cette situation est plus fréquente qu''on ne le croit, et elle vient presque toujours du même endroit : un nom de domaine déposé au nom du prestataire, ou un renouvellement oublié.</p> <p>Le nom de domaine est pourtant l''un des actifs les plus simples à protéger. Voici comment le choisir, le déposer et le garder.</p> <h2>Qu''est-ce qu''un nom de domaine ?</h2> <p>C''est l''adresse de votre site (par exemple <em>menuiserie-payet.re</em>) et la deuxième moitié de vos adresses e-mail (<em>contact@menuiserie-payet.re</em>). Vous ne l''achetez pas une fois pour toutes : vous le louez, en général à l''année, auprès d''un bureau d''enregistrement, qui le déclare auprès du registre de l''extension. Pour les extensions .fr et .re, ce registre est l''<a href="https://www.afnic.fr/noms-de-domaine/tout-savoir/" target="_blank" rel="noopener">Afnic</a>.</p> <h2>Bien choisir le nom</h2> <ul class="checklist"> <li><strong>Court et facile à dicter.</strong> Faites le test du téléphone : si vous devez l''épeler deux fois, il est trop compliqué.</li> <li><strong>Proche du nom de l''entreprise.</strong> Le client doit pouvoir le deviner. Un mot-clé peut aider (<em>plomberie-hoarau</em>), à condition de rester lisible.</li> <li><strong>Sans caractères pièges.</strong> Évitez les accents, les chiffres ambigus et les tirets multiples.</li> <li><strong>Libre de droits.</strong> Vérifiez qu''il ne reprend pas une marque ou le nom d''un concurrent.</li> <li><strong>Pensé pour durer.</strong> Évitez d''y mettre une commune si vous comptez vous étendre à toute l''île.</li> </ul> <h2>.re, .fr ou .com ?</h2> <table class="table-article"> <thead><tr><th>Extension</th><th>Ce qu''elle dit de vous</th><th>Pour qui</th></tr></thead> <tbody> <tr><td>.re</td><td>Entreprise ancrée à La Réunion</td><td>Commerces et services qui travaillent surtout sur l''île</td></tr> <tr><td>.fr</td><td>Entreprise française</td><td>Clientèle en métropole et à La Réunion</td></tr> <tr><td>.com</td><td>Extension la plus connue, sans ancrage géographique</td><td>Activité tournée vers l''international, ou si le .re et le .fr sont pris</td></tr> </tbody> </table> <p>Une solution courante consiste à réserver le .re et le .fr (voire le .com), puis à rediriger les autres vers celui que vous utilisez. Le coût reste modeste, et personne ne pourra prendre votre nom avec une autre extension.</p> <h2>Le déposer correctement</h2> <ol class="etapes"> <li><strong>Votre entreprise comme titulaire.</strong> Le nom doit être enregistré au nom de votre société ou de votre entreprise individuelle, avec ses vraies coordonnées. Si un prestataire s''occupe du dépôt, demandez-lui de le faire à votre nom, et vérifiez-le.</li> <li><strong>Une adresse e-mail que vous contrôlez.</strong> L''adresse de contact du nom de domaine reçoit les alertes de renouvellement : elle doit être la vôtre, et toujours active.</li> <li><strong>Le renouvellement automatique.</strong> Activez-le, avec un moyen de paiement à jour. Un nom expiré peut être racheté par quelqu''un d''autre.</li> <li><strong>Vos accès notés en lieu sûr.</strong> Identifiant du compte chez le bureau d''enregistrement, et double authentification activée.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un restaurant à Saint-Gilles</p> <p>Son site et ses e-mails fonctionnaient depuis des années, jusqu''au jour où ils se sont arrêtés : le nom de domaine, déposé par un ancien prestataire, n''avait pas été renouvelé. Après l''avoir récupéré, le gérant le fait transférer sur un compte au nom du restaurant, active le renouvellement automatique et ajoute une deuxième personne de confiance comme contact.</p> </div> <h2>Les e-mails professionnels</h2> <p>Une adresse <em>prenom@votre-entreprise.re</em> inspire plus confiance qu''une adresse gratuite, et elle reste la vôtre si vous changez de fournisseur de messagerie. Prévoyez au moins une adresse générique (<em>contact@</em>) que plusieurs personnes peuvent consulter, et des adresses nominatives pour l''équipe.</p> <h2>Changer de prestataire sans rien perdre</h2> <p>Si le nom est bien à votre nom, changer de prestataire est simple : vous demandez le code de transfert (ou code d''autorisation) à l''ancien bureau d''enregistrement, et le nouveau s''occupe du reste. Le site et les e-mails peuvent continuer à fonctionner pendant l''opération si elle est bien préparée.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous vous aidons à choisir votre nom de domaine et vérifions avec vous qu''il est bien déposé au nom de votre entreprise. Site vitrine à partir de 990 € (690 € si vous avez déjà un logo), puis 49 €/mois de maintenance sur 12 mois, hébergement compris. Nous pouvons aussi vérifier à qui appartient votre nom de domaine actuel.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Qui peut déposer un nom de domaine en .re ?</h3> <p>Le .re est géré par l''Afnic. Il est ouvert aux personnes qui résident et aux entreprises établies dans l''Union européenne et dans quelques pays voisins, pas seulement à La Réunion. Le dépôt se fait auprès d''un bureau d''enregistrement.</p> <h3>Comment savoir à qui appartient mon nom de domaine ?</h3> <p>Connectez-vous au compte de votre bureau d''enregistrement, ou demandez à votre prestataire de vous montrer le titulaire déclaré. Le titulaire doit être votre entreprise. Si ce n''est pas le cas, demandez une mise à jour du titulaire ou un transfert vers un compte à votre nom.</p> <h3>Que se passe-t-il si mon nom de domaine expire ?</h3> <p>Le site et les e-mails cessent de fonctionner. Après une période de rattrapage, le nom peut redevenir disponible et être déposé par quelqu''un d''autre. Activez le renouvellement automatique pour éviter ce risque.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.afnic.fr/noms-de-domaine/tout-savoir/" target="_blank" rel="noopener">Afnic : tout savoir sur les noms de domaine</a>.</li> <li><a href="https://www.afnic.fr/" target="_blank" rel="noopener">Afnic</a>, registre des extensions .fr et .re.</li> <li><a href="/blog/prix-site-internet-reunion">Prix d''un site internet à La Réunion : le vrai coût</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Nom de domaine d''entreprise : le choisir et le garder', '.re, .fr ou .com ? Comment choisir le nom de domaine de votre entreprise à La Réunion, le déposer à votre nom et ne jamais le perdre.', 'nom de domaine entreprise, nom de domaine .re, choisir nom de domaine, adresse mail professionnelle, Réunion', '/assets/images/blog/nom-de-domaine-entreprise.webp', '/assets/images/blog/nom-de-domaine-entreprise.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Newsletter : faut-il en envoyer une quand on est une TPE ?', 'newsletter-tpe', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'E-mail marketing', 'Vos clients vous oublient entre deux achats. Une newsletter simple, une fois par mois, peut les faire revenir. Ce qu''il faut y mettre, et les règles à respecter.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une newsletter est utile si vos clients peuvent revenir : commerce, restauration, beauté, entretien, formation. Elle l''est moins pour un achat unique tous les dix ans.</li> <li>Une fois par mois suffit, avec un contenu utile (nouveautés, conseils, offres réservées) plutôt qu''une simple publicité.</li> <li>Pour écrire à des particuliers, il faut leur accord préalable, sauf pour vos clients existants à propos de produits ou services similaires. Chaque envoi doit permettre de se désinscrire.</li> </ul> </div> <p>Sur les réseaux sociaux, vos publications ne sont vues que par une partie de vos abonnés, et c''est la plateforme qui décide. L''e-mail, lui, arrive dans la boîte de chaque personne inscrite. C''est l''un des rares canaux qui vous appartient vraiment : la liste d''adresses est à vous, pas à Facebook.</p> <p>Encore faut-il que la newsletter donne envie d''être ouverte, et qu''elle respecte les règles. Voici comment s''y prendre quand on est une petite entreprise.</p> <h2>Une newsletter, pour qui ?</h2> <table class="table-article"> <thead><tr><th>Activité</th><th>Intérêt</th><th>Ce qu''on peut envoyer</th></tr></thead> <tbody> <tr><td>Commerce, boutique en ligne</td><td>Fort</td><td>Nouveautés, arrivages, offres réservées aux abonnés</td></tr> <tr><td>Restaurant, traiteur</td><td>Fort</td><td>Menus du mois, soirées, commandes pour les fêtes</td></tr> <tr><td>Beauté, bien-être, sport</td><td>Fort</td><td>Conseils de saison, créneaux disponibles, nouvelles prestations</td></tr> <tr><td>Artisan, entretien</td><td>Moyen</td><td>Rappel d''entretien annuel, conseils avant la saison cyclonique</td></tr> <tr><td>Achat rare et ponctuel</td><td>Faible</td><td>Mieux vaut un e-mail de suivi après la prestation</td></tr> </tbody> </table> <h2>Ce qu''il faut mettre dedans</h2> <p>La règle la plus simple : un message principal, et un seul bouton. Un e-mail court, lisible sur téléphone, se lit ; un catalogue de dix rubriques, non.</p> <ol class="etapes"> <li><strong>Un objet qui donne envie</strong>, précis et court : « Les letchis sont arrivés » plutôt que « Newsletter n° 12 ».</li> <li><strong>Une information utile</strong> : une nouveauté, un conseil, une date à retenir.</li> <li><strong>Une photo</strong>, la vôtre, plutôt qu''une image de banque.</li> <li><strong>Un bouton</strong> vers l''action attendue : réserver, commander, voir la nouveauté.</li> <li><strong>Le lien de désinscription</strong> en bas, bien visible, et vos coordonnées.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">E-mail mensuel type, à adapter</p> <p>Objet : « Votre jardin avant les pluies ». Trois lignes pour expliquer pourquoi tailler avant janvier, une photo d''un jardin entretenu, un bouton « Réserver un passage », et la mention « Créneaux limités en décembre ». C''est tout.</p> </div> <h2>Les règles à respecter</h2> <p>La <a href="https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique" target="_blank" rel="noopener">CNIL détaille les règles</a> de la prospection par e-mail :</p> <ul> <li><strong>Particuliers</strong> : il faut leur accord préalable, donné par une action claire (une case à cocher non pré-cochée, par exemple). Exception : vos clients existants peuvent recevoir des offres pour des produits ou services similaires à ceux qu''ils ont achetés, s''ils ont été informés et ont pu s''y opposer.</li> <li><strong>Professionnels</strong> : l''envoi est possible sans accord préalable, si le message concerne leur métier et qu''ils ont été informés et peuvent s''y opposer.</li> <li><strong>Dans tous les cas</strong> : un lien de désinscription simple dans chaque e-mail, votre identité clairement indiquée, et pas d''achat de fichiers d''adresses douteux.</li> </ul> <h2>Faire grandir sa liste</h2> <ul class="checklist"> <li>Un formulaire d''inscription sur votre site, avec ce que l''abonné va recevoir et à quelle fréquence.</li> <li>La proposition à la caisse ou à la fin d''une prestation, avec l''accord noté.</li> <li>Un avantage concret pour s''inscrire : une invitation, un conseil, une offre de bienvenue.</li> <li>Le lien d''inscription sur vos réseaux sociaux et dans votre signature d''e-mail.</li> </ul> <h2>Mesurer ce qui marche</h2> <p>Les outils d''envoi indiquent combien de personnes ont ouvert l''e-mail et cliqué sur le bouton. Regardez surtout les clics et ce qui se passe ensuite : réservations, commandes, appels. Si un sujet fonctionne mieux que les autres, refaites-en.</p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une épicerie fine à Saint-Denis</p> <p>Elle collecte les adresses à la caisse, avec l''accord des clients, et envoie un e-mail le premier jeudi du mois : les arrivages, une recette avec un produit de la boutique, et une dégustation à venir. Les clients mentionnent souvent l''e-mail en venant en boutique, ce qui lui confirme que le rendez-vous mensuel est attendu.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nous préparons et envoyons vos newsletters chaque mois : à partir de 190 €/mois avec vos contenus, 290 €/mois avec la rédaction incluse. Nous pouvons aussi mettre en place des e-mails automatiques (bienvenue, relance, panier abandonné) à partir de 490 €, payés une fois.</p> <p><a href="/services#email-marketing" class="encadre-lien">Voir l''offre E-mail marketing</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>À quelle fréquence envoyer une newsletter ?</h3> <p>Une fois par mois est un bon rythme pour une TPE : assez pour que les clients ne vous oublient pas, sans les lasser. Mieux vaut un envoi mensuel régulier et utile qu''un envoi hebdomadaire sans contenu.</p> <h3>Peut-on envoyer une newsletter sans consentement ?</h3> <p>Pour des particuliers, non, sauf à vos clients existants pour des produits ou services similaires, s''ils ont été informés et ont pu refuser. Pour des professionnels, c''est possible si le message concerne leur activité et qu''ils peuvent s''y opposer facilement.</p> <h3>Quel outil utiliser pour envoyer une newsletter ?</h3> <p>Utilisez un outil d''e-mailing dédié plutôt que votre messagerie habituelle : il gère les désinscriptions, la mise en page sur téléphone et les statistiques. Plusieurs proposent une formule gratuite pour les petites listes.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique" target="_blank" rel="noopener">CNIL : la prospection commerciale par courrier électronique</a>.</li> <li><a href="https://www.cnil.fr/fr/passer-laction/rgpd-les-premieres-etapes" target="_blank" rel="noopener">CNIL : RGPD, les premières étapes</a>.</li> <li><a href="/blog/rgpd-tpe-essentiel">RGPD pour une TPE : l''essentiel en 7 étapes</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Newsletter pour TPE : utile ou pas, et comment s''y prendre', 'Fréquence, contenu, consentement, outils : comment lancer une newsletter utile pour une petite entreprise, sans spammer vos clients ni enfreindre le RGPD.', 'newsletter TPE, e-mail marketing petite entreprise, consentement newsletter RGPD, fidéliser clients e-mail', '/assets/images/blog/newsletter-tpe.webp', '/assets/images/blog/newsletter-tpe.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('30 idées de publications pour les réseaux sociaux d''une TPE', 'idees-publications-reseaux-sociaux', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', '« Je ne sais pas quoi publier. » Voici 30 idées concrètes, classées en six familles, et une méthode pour préparer un mois de publications en une heure.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Le manque d''idées vient souvent d''un manque de méthode : en classant ses publications en six familles, on ne repart plus jamais de zéro.</li> <li>Les publications qui marchent le mieux pour une TPE montrent des vraies personnes, des vrais chantiers ou produits, et l''envers du décor.</li> <li>Une heure par mois suffit pour préparer et programmer huit publications, soit deux par semaine.</li> </ul> </div> <p>Vous savez qu''il faudrait publier régulièrement sur Facebook et Instagram. Mais le lundi matin, devant l''écran, rien ne vient. Alors on publie une promotion, puis plus rien pendant trois semaines, et la page s''endort.</p> <p>Voici 30 idées classées en six familles, adaptées à une petite entreprise réunionnaise, et une méthode pour préparer un mois de publications d''un coup.</p> <h2>1. Montrer votre travail</h2> <ul> <li>Un avant / après : chantier, coupe, jardin, véhicule, pièce rénovée.</li> <li>Une réalisation récente, avec la commune et une phrase sur la difficulté rencontrée.</li> <li>Un produit en situation, dans les mains d''un client (avec son accord).</li> <li>Une vidéo de 15 secondes d''un geste technique.</li> <li>Votre réalisation préférée de l''année, et pourquoi.</li> </ul> <h2>2. L''envers du décor</h2> <ul> <li>Le début de votre journée : la préparation, l''ouverture, le premier café.</li> <li>Un membre de l''équipe présenté en trois questions.</li> <li>L''arrivée d''une livraison ou d''une nouvelle machine.</li> <li>Une erreur qui vous a appris quelque chose.</li> <li>Pourquoi vous avez créé l''entreprise.</li> </ul> <h2>3. Conseiller</h2> <ul> <li>Une astuce d''entretien liée à votre métier.</li> <li>L''erreur la plus fréquente que font vos clients, et comment l''éviter.</li> <li>Trois questions à poser avant de choisir un professionnel comme vous.</li> <li>Un conseil de saison : avant les pluies, avant les fêtes, avant la rentrée.</li> <li>La réponse à une question que l''on vous pose souvent.</li> </ul> <h2>4. Créer le lien</h2> <ul> <li>Un sondage simple : « Plutôt A ou B ? »</li> <li>Une question ouverte : « Quel est votre plat de fin d''année préféré ? »</li> <li>Un avis client reçu cette semaine, avec un merci.</li> <li>Une photo partagée par un client (avec son accord).</li> <li>Un jeu concours, en respectant les règles de la plateforme.</li> </ul> <h2>5. Être d''ici</h2> <ul> <li>Un clin d''œil au calendrier réunionnais : 20 décembre, rentrée de janvier, fruits de saison.</li> <li>Un partenaire ou un fournisseur local mis en avant.</li> <li>Votre participation à un événement de la commune.</li> <li>Un message pratique en cas d''alerte cyclonique ou de fermeture exceptionnelle.</li> <li>Un coin de votre quartier que vous aimez.</li> </ul> <h2>6. Vendre, sans en abuser</h2> <ul> <li>Une nouveauté, avec une vraie photo et le prix.</li> <li>Les créneaux disponibles de la semaine.</li> <li>Une offre limitée dans le temps, avec la date de fin.</li> <li>Un rappel des modes de contact et de réservation.</li> <li>La date limite pour commander avant les fêtes.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">La règle des proportions</p> <p>Sur huit publications dans le mois, gardez-en au plus deux qui vendent directement. Les six autres montrent, conseillent et créent du lien : ce sont elles qui donnent envie de vous choisir le jour où le besoin arrive.</p> </div> <h2>Préparer un mois en une heure</h2> <ul class="checklist"> <li>Choisissez huit idées dans la liste, en variant les familles.</li> <li>Prenez ou retrouvez les photos dans votre téléphone ; une vraie photo vaut mieux qu''une belle image de banque.</li> <li>Rédigez les textes d''un coup, courts, avec une question ou une action à la fin.</li> <li>Programmez-les dans Meta Business Suite, qui publie sur Facebook et Instagram en même temps.</li> <li>Notez ce qui a le mieux marché à la fin du mois, pour en refaire.</li> </ul> <p>Pour vous aider, notre <a href="/outils/calendrier-editorial">générateur de calendrier éditorial</a> gratuit propose un planning de publications selon votre activité. Et si vous hésitez entre les deux réseaux, lisez <a href="/blog/instagram-ou-facebook-reunion">Instagram ou Facebook : où sont vos clients à La Réunion ?</a></p> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une boulangerie à Saint-André</p> <p>Elle ne publiait que ses promotions, et peu de monde réagissait. Elle prépare désormais chaque mois huit publications : la fournée du matin en vidéo, une apprentie présentée en trois questions, un conseil pour conserver le pain, et seulement deux offres. Les commentaires et les partages augmentent, et les clients parlent des vidéos en boutique.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Pas le temps de publier ? Nous préparons et programmons vos publications chaque mois : 8 publications pour 290 €/mois, ou le community management complet (12 publications, modération, bilan mensuel) pour 390 €/mois.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/outils/calendrier-editorial" class="encadre-lien">Générer mon calendrier gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien de fois par semaine publier sur Facebook et Instagram ?</h3> <p>Pour une TPE, deux publications par semaine tenues dans la durée valent mieux qu''une publication par jour pendant deux semaines puis plus rien. La régularité compte plus que la quantité.</p> <h3>Quel type de publication fonctionne le mieux pour une petite entreprise ?</h3> <p>Les publications qui montrent des vraies personnes et des vraies réalisations : avant / après, coulisses, présentation de l''équipe, vidéos courtes. Les promotions seules attirent peu de réactions si elles ne sont pas entourées de contenus utiles.</p> <h3>Peut-on programmer ses publications à l''avance ?</h3> <p>Oui. Meta Business Suite permet de programmer gratuitement des publications sur Facebook et Instagram. Vous pouvez préparer tout le mois en une séance et ajouter ensuite des publications spontanées.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="https://www.facebook.com/business/tools/meta-business-suite" target="_blank" rel="noopener">Meta Business Suite</a> : programmation des publications Facebook et Instagram.</li> <li><a href="/blog/instagram-ou-facebook-reunion">Instagram ou Facebook : où sont vos clients à La Réunion ?</a></li> <li><a href="/outils/calendrier-editorial">Générateur de calendrier éditorial DIGITA</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', '30 idées de publications Facebook et Instagram pour TPE', 'En panne d''inspiration ? 30 idées de publications Facebook et Instagram classées par thème, pour une TPE réunionnaise, et la méthode pour planifier un mois.', 'idées publications Facebook, idées posts Instagram, quoi publier réseaux sociaux, calendrier éditorial TPE', '/assets/images/blog/idees-publications-reseaux-sociaux.webp', '/assets/images/blog/idees-publications-reseaux-sociaux.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Landing page : à quoi ça sert, et quand en faire une ?', 'landing-page-definition', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Sites web et landing', 'Une page, un message, une action. La landing page est souvent le meilleur point de départ pour une offre précise ou une campagne publicitaire. Mode d''emploi.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une landing page (page d''atterrissage) est une page unique, construite autour d''un seul objectif : un appel, une demande de devis, une réservation, une inscription.</li> <li>Elle est idéale pour une offre précise, une campagne publicitaire ou un lancement, et comme premier pas en ligne quand le budget est serré.</li> <li>Un site vitrine présente toute l''entreprise ; une landing page pousse à une action. Les deux se complètent.</li> </ul> </div> <p>Vous lancez une publicité sur Facebook pour votre nouvelle offre de nettoyage de toiture. Le client clique… et arrive sur la page d''accueil de votre site, où il doit chercher l''offre parmi tout le reste. Une partie des visiteurs abandonne avant de la trouver. C''est exactement le problème que règle une landing page.</p> <p>Voici ce qu''est une landing page, quand elle est utile, et ce qu''elle doit contenir pour transformer les visiteurs en contacts.</p> <h2>Landing page ou site vitrine ?</h2> <table class="table-article"> <thead><tr><th>Critère</th><th>Landing page</th><th>Site vitrine</th></tr></thead> <tbody> <tr><td>Nombre de pages</td><td>Une seule</td><td>Plusieurs (souvent 5 ou plus)</td></tr> <tr><td>Objectif</td><td>Une action précise</td><td>Présenter toute l''entreprise</td></tr> <tr><td>Navigation</td><td>Réduite au minimum, pour ne pas distraire</td><td>Menu complet</td></tr> <tr><td>Usage typique</td><td>Publicité, offre, lancement, premier pas en ligne</td><td>Être trouvé sur Google, inspirer confiance sur la durée</td></tr> <tr><td>Délai de création</td><td>Quelques jours</td><td>Quelques semaines</td></tr> </tbody> </table> <h2>Quand faire une landing page</h2> <ul class="checklist"> <li>Vous lancez une <a href="/blog/budget-publicite-facebook-reunion">campagne publicitaire</a> et voulez une page qui parle exactement de ce que la publicité promet.</li> <li>Vous avez une offre précise à mettre en avant : une prestation de saison, un forfait, un événement.</li> <li>Vous démarrez sans site et voulez être présent en ligne rapidement, avec un formulaire de contact.</li> <li>Vous voulez tester une nouvelle activité avant d''investir dans un site complet.</li> <li>Vous voulez recueillir des inscriptions : atelier, liste d''attente, guide à télécharger.</li> </ul> <h2>Ce qu''une bonne landing page contient</h2> <ol class="etapes"> <li><strong>Un titre qui reprend la promesse.</strong> Le même message que la publicité ou le lien qui y mène : le visiteur doit se dire « c''est bien ici ».</li> <li><strong>Le bénéfice pour le client</strong>, en trois ou quatre points courts : ce qu''il obtient, en combien de temps, pour quel prix ou à partir de quel prix.</li> <li><strong>Des preuves</strong> : photos de vraies réalisations, avis clients, années d''expérience, garanties.</li> <li><strong>Un seul appel à l''action</strong>, répété plusieurs fois : « Demander mon devis », « Réserver », « Appeler ». Pas cinq boutons différents.</li> <li><strong>Un formulaire court</strong> : nom, téléphone ou e-mail, et une ou deux questions utiles. Chaque champ en plus fait perdre des contacts.</li> <li><strong>Les réponses aux objections</strong> : une petite foire aux questions sur les délais, la zone, le paiement.</li> <li><strong>Les mentions obligatoires</strong> : mentions légales, politique de confidentialité, et bandeau cookies si nécessaire.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Structure type, à adapter</p> <p>Titre : « Nettoyage et démoussage de toiture dans l''Ouest, devis en 48 h ». Puis trois avantages, quatre photos avant / après, deux avis Google, un formulaire (nom, téléphone, commune, photo de la toiture), une FAQ de quatre questions, et le bouton « Demander mon devis » en haut, au milieu et en bas de la page.</p> </div> <h2>Les erreurs fréquentes</h2> <ul> <li><strong>Le menu complet du site</strong> : chaque lien est une porte de sortie. Gardez seulement le logo et le contact.</li> <li><strong>Un message différent de la publicité</strong> : le visiteur pense s''être trompé et repart.</li> <li><strong>Une page lente sur téléphone</strong> : la plupart des visiteurs viennent des réseaux sociaux, donc d''un mobile. Allégez les images.</li> <li><strong>Aucun suivi</strong> : sans mesure des demandes reçues, impossible de savoir si la page et la publicité sont rentables.</li> </ul> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un installateur de chauffe-eau solaires à Saint-Pierre</p> <p>Ses publicités renvoyaient vers la page d''accueil de son site, qui présentait aussi l''électricité générale et la climatisation. Il crée une landing page dédiée aux chauffe-eau solaires, avec le même titre que la publicité, des photos de poses et un formulaire de quatre champs. Les demandes reçues concernent désormais presque toutes cette offre, et il sait combien chacune lui coûte en publicité.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>La Landing Essentielle, une page avec formulaire de contact, coûte 499 €, livrée en 5 jours ouvrés. Pour une page rédigée par nos soins, comptez 790 €. Si votre activité grandit, la landing page peut devenir la base d''un site vitrine (à partir de 990 €).</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Qu''est-ce qu''une landing page ?</h3> <p>C''est une page web unique, conçue pour une seule action : demander un devis, réserver, appeler ou s''inscrire. Elle est souvent utilisée comme destination d''une publicité ou pour présenter une offre précise.</p> <h3>Une landing page peut-elle remplacer un site internet ?</h3> <p>Pour démarrer, oui : elle suffit pour présenter une activité simple et recevoir des demandes. Quand vous voulez être trouvé sur Google pour plusieurs services ou montrer de nombreuses réalisations, un site vitrine de plusieurs pages devient plus adapté.</p> <h3>Une landing page est-elle bien référencée sur Google ?</h3> <p>Elle peut l''être pour une recherche précise, mais une seule page a moins de chances qu''un site complet de ressortir sur de nombreuses recherches. Une landing page sert surtout à convertir le trafic que vous lui envoyez : publicité, réseaux sociaux, e-mail.</p> <div class="article-sources"> <p class="encadre-titre">Pour aller plus loin</p> <ul> <li><a href="/blog/site-vitrine-ou-page-facebook">Site vitrine ou page Facebook : que choisir pour une entreprise à La Réunion ?</a></li> <li><a href="/blog/budget-publicite-facebook-reunion">Pub Facebook à La Réunion : quel budget pour démarrer ?</a></li> <li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">Google : guide de démarrage en référencement (SEO)</a>.</li> <li><a href="https://entreprendre.service-public.fr/vosdroits/F31228" target="_blank" rel="noopener">Service Public Entreprendre : cookies et site d''entreprise</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Landing page : définition, usages et erreurs à éviter', 'Une landing page est une page unique avec un seul objectif. Quand en créer une, ce qu''elle doit contenir et en quoi elle diffère d''un site vitrine.', 'landing page définition, page d''atterrissage, landing page publicité, créer landing page, landing page Réunion', '/assets/images/blog/landing-page-definition.webp', '/assets/images/blog/landing-page-definition.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Page Facebook piratée : prévenir, réagir, récupérer', 'page-facebook-piratee', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Un faux message « Meta Support », un clic, et la page de l''entreprise n''est plus à vous. Les réglages qui protègent, et les bons réflexes si c''est déjà arrivé.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>La plupart des pages d''entreprise piratées le sont après un faux message : « violation des droits d''auteur », « votre page va être supprimée », signé d''un faux service Meta.</li> <li>Trois réglages protègent l''essentiel : la double authentification, au moins deux administrateurs de confiance, et une adresse e-mail de récupération sécurisée.</li> <li>Si c''est déjà arrivé : sécuriser votre compte personnel, passer par la procédure officielle de Meta, prévenir vos clients, garder des preuves, et vous faire aider par Cybermalveillance.gouv.fr.</li> </ul> </div> <p>Un matin, le gérant reçoit un message : « Votre page a enfreint nos règles et sera désactivée sous 24 h. Cliquez ici pour faire appel. » Le logo ressemble à celui de Meta, le ton est pressant. Il clique, se connecte… et quelques minutes plus tard, il n''a plus accès à la page de l''entreprise, qui publie des publicités frauduleuses à ses abonnés.</p> <p>Ce scénario touche régulièrement des commerçants et artisans. Voici comment l''éviter, et quoi faire si c''est trop tard.</p> <h2>Comment les pirates s''y prennent</h2> <table class="table-article"> <thead><tr><th>Technique</th><th>À quoi ça ressemble</th><th>Le bon réflexe</th></tr></thead> <tbody> <tr><td>Faux avertissement</td><td>« Votre page sera supprimée », lien vers un faux formulaire</td><td>Ne jamais cliquer ; vérifier dans l''Espace comptes ou la Business Suite</td></tr> <tr><td>Faux partenariat</td><td>Une marque propose une collaboration et envoie un fichier « contrat »</td><td>Ne pas ouvrir de fichier inconnu, surtout compressé</td></tr> <tr><td>Mot de passe réutilisé</td><td>Le même mot de passe a fuité sur un autre site</td><td>Un mot de passe unique par compte</td></tr> <tr><td>Code de connexion demandé</td><td>Un « ami » demande le code reçu par SMS</td><td>Ne jamais transmettre un code de vérification</td></tr> </tbody> </table> <h2>Les réglages qui protègent</h2> <ul class="checklist"> <li><strong>La double authentification</strong> sur le compte Facebook personnel de chaque administrateur, de préférence avec une application d''authentification plutôt que par SMS.</li> <li><strong>Au moins deux administrateurs de confiance</strong> avec un accès complet, pour pouvoir reprendre la main si l''un des comptes est compromis.</li> <li><strong>Des droits limités</strong> pour les autres : un salarié ou un prestataire qui publie n''a pas besoin d''un accès complet.</li> <li><strong>Une adresse e-mail et un numéro de récupération à jour</strong>, et une messagerie elle-même protégée par double authentification.</li> <li><strong>Un mot de passe unique et long</strong>, rangé dans un gestionnaire de mots de passe.</li> <li><strong>Un ménage régulier</strong> : retirer les anciens salariés et prestataires des accès, vérifier les appareils connectés.</li> </ul> <p>La CNIL détaille ces mesures dans sa fiche <a href="https://www.cnil.fr/fr/prevenir-reperer-et-reagir-face-au-piratage-de-ses-comptes-sociaux" target="_blank" rel="noopener">Prévenir, repérer et réagir face au piratage de ses comptes sociaux</a>.</p> <h2>Si votre page a été piratée</h2> <ol class="etapes"> <li><strong>Sécuriser votre compte personnel.</strong> Si vous y avez encore accès, changez le mot de passe, activez la double authentification et déconnectez les sessions inconnues. Sinon, passez par la procédure de compte piraté de Meta, sur <a href="https://www.facebook.com/hacked" target="_blank" rel="noopener">facebook.com/hacked</a>.</li> <li><strong>Faire agir le deuxième administrateur.</strong> S''il a toujours accès, il peut retirer l''administrateur inconnu et rétablir vos droits.</li> <li><strong>Vérifier la messagerie liée.</strong> Changez aussi le mot de passe de l''adresse e-mail du compte, et supprimez les règles de transfert que vous n''avez pas créées.</li> <li><strong>Prévenir vos clients</strong> par vos autres canaux (WhatsApp, site, fiche Google, e-mail) : « Notre page Facebook a été piratée, ne donnez suite à aucun message ni lien venant d''elle. »</li> <li><strong>Garder des preuves</strong> : captures d''écran des messages reçus, des publications frauduleuses, des e-mails de modification de compte.</li> <li><strong>Vous faire aider et signaler.</strong> La plateforme <a href="https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/piratage-de-compte" target="_blank" rel="noopener">Cybermalveillance.gouv.fr</a> et le service <a href="https://www.17cyber.gouv.fr/" target="_blank" rel="noopener">17Cyber</a> orientent les victimes. Si des clients ont été escroqués en votre nom, déposez plainte.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Modèle de message à vos clients, à adapter</p> <p>« Attention : notre page Facebook a été piratée ce matin. Nous ne vous demanderons jamais de paiement ni de code par message. Ne cliquez sur aucun lien venant de cette page tant que nous ne l''avons pas récupérée. Pour nous joindre : [téléphone] ou [site]. Merci de partager ce message. »</p> </div> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un salon de coiffure à Saint-Paul</p> <p>La gérante était la seule administratrice de la page. Après un faux message « Meta Support », elle perd l''accès, et il lui faut plusieurs semaines pour récupérer la page via la procédure officielle. Elle ajoute ensuite son associée comme deuxième administratrice, active la double authentification sur les deux comptes et prévient ses clientes sur WhatsApp au moindre doute.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Quand nous gérons vos réseaux sociaux (à partir de 290 €/mois), vous restez propriétaire et administrateur de vos pages : un prestataire n''a besoin que des droits utiles à son travail. Pas encore de page ? Le Pack de lancement (logo et page Facebook professionnelle) coûte 499 €.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/solutions#lancement" class="encadre-lien">Le Pack de lancement</a></p> </div> <h2>Questions fréquentes</h2> <h3>Comment savoir si un message de Meta est un faux ?</h3> <p>Meta ne vous menace pas de supprimer votre page par message privé avec un lien externe. En cas de doute, ne cliquez pas : vérifiez directement les alertes dans l''Espace comptes ou dans Meta Business Suite. Une adresse de lien qui n''est pas facebook.com ou meta.com est un signal d''alerte.</p> <h3>Comment récupérer une page Facebook piratée ?</h3> <p>Commencez par récupérer votre compte personnel via facebook.com/hacked, puis rétablissez vos droits sur la page, ou demandez au deuxième administrateur de le faire. Prévenez vos clients par d''autres canaux et gardez des preuves. Cybermalveillance.gouv.fr peut vous orienter.</p> <h3>Combien d''administrateurs faut-il sur une page Facebook d''entreprise ?</h3> <p>Au moins deux personnes de confiance avec un accès complet, chacune avec la double authentification activée. Les salariés et prestataires doivent avoir uniquement les droits dont ils ont besoin.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.cnil.fr/fr/prevenir-reperer-et-reagir-face-au-piratage-de-ses-comptes-sociaux" target="_blank" rel="noopener">CNIL : prévenir, repérer et réagir face au piratage de ses comptes sociaux</a>.</li> <li><a href="https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/piratage-de-compte" target="_blank" rel="noopener">Cybermalveillance.gouv.fr : piratage de compte</a>.</li> <li><a href="https://www.17cyber.gouv.fr/" target="_blank" rel="noopener">17Cyber</a> : diagnostic et assistance aux victimes.</li> <li><a href="https://www.facebook.com/hacked" target="_blank" rel="noopener">Facebook : signaler un compte piraté</a>.</li> </ul> </div>', 'Page Facebook piratée : prévenir, réagir et la récupérer', 'Faux messages de Meta, mot de passe volé, administrateur inconnu : comment protéger la page Facebook de votre entreprise et quoi faire si elle est piratée.', 'page Facebook piratée, compte Facebook piraté entreprise, sécuriser page Facebook, double authentification, phishing Meta', '/assets/images/blog/page-facebook-piratee.webp', '/assets/images/blog/page-facebook-piratee.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;
